/**
 * Bienestar UPEMOR — Inicialización de Bootstrap 5 y Componentes Interactivos.
 *
 * Expone la biblioteca Bootstrap 5 en el objeto global `window.bootstrap`
 * para el manejo de modales, alertas dinámicas, tooltips y desplegables.
 *
 * @module resources/js/bootstrap-app
 */

import './bootstrap';
import * as bootstrap from 'bootstrap';

window.bootstrap = bootstrap;
